import {icon} from './art.mjs';

/** Render authored profile UI; identity and class values are escaped by the host. */
export function renderProfileView({profile, classes, signedIn, confirming = false, accountHeading, avatarArt, button, field, formError, submit, esc, t}) {
  if (!signedIn) return `<section class="portal-panel"><h1 id="portal-title" tabindex="-1">${t('Profil Saya')}</h1><p>${t('Anda sedang menggunakan mod tetamu. Log masuk untuk melihat dan menyimpan profil akaun anda.')}</p>${button(t('Log masuk'), 'profile-login', {primary: true})}</section>`;
  const email = profile.email;
  const legacy = typeof email !== 'string' || email.endsWith('@accounts.geodecoder.invalid');
  const choices = [['initial', 'Inisial'], ['cube', 'Kubus'], ['cuboid', 'Kuboid'], ['pyramid', 'Piramid'], ['cylinder', 'Silinder'], ['cone', 'Kon']];
  const role = t(profile.role === 'teacher' ? 'Guru' : profile.role === 'student' ? 'Murid' : 'Belum tersedia');
  const classNames = classes.map(c => esc(c.name));
  return `<div class="portal-profile-workspace">${accountHeading(t('AKAUN ANDA'), `<span class="portal-account-heading-icon" aria-hidden="true">${icon('user')}</span>${t('Profil Saya')}`, t('Urus maklumat dan penampilan akaun anda di GeoMath.'))}
    <div class="portal-utility-navigation portal-account-shortcuts">${button(t('Kembali ke kelas'), 'profile-back', {quiet: true, symbol: 'home'})}${button(t('Tetapan Penggunaan'), 'profile-settings', {quiet: true})}${button(t('Kata Laluan & Keselamatan'), 'security', {quiet: true, symbol: 'lock'})}</div>
    ${confirming ? `<section class="portal-panel portal-profile-confirm" role="group" aria-labelledby="profile-unsaved-title"><h2 id="profile-unsaved-title">${t('Perubahan belum disimpan')}</h2><p>${t('Simpan nama dan avatar sebelum keluar, atau buang perubahan ini.')}</p><div class="dialog-actions">${button(t('Teruskan menyunting'), 'profile-stay', {quiet: true})}${button(t('Buang perubahan'), 'profile-discard', {danger: true})}${button(t('Simpan dan teruskan'), 'profile-save-leave', {primary: true})}</div></section>` : ''}
    <div class="portal-profile-layout"><section class="portal-panel portal-profile-editor" aria-label="${t('Nama & avatar')}"><form data-portal-form="profile" novalidate>
      <fieldset class="portal-avatar-options"><legend>${t('Pilih avatar')}</legend><div class="portal-avatar-strip">${choices.map(([id, label]) => `<label><input id="portal-avatar-${id}" type="radio" name="avatar" value="${id}" ${id === (profile.avatar || 'initial') ? 'checked' : ''} required><span class="portal-avatar">${avatarArt(id)}</span><span class="portal-avatar-label">${t(label)}</span></label>`).join('')}</div></fieldset>
      ${field('portal-profile-name', t('Nama paparan'), {name: 'display_name', autocomplete: 'nickname', min: 2, max: 60, value: profile.display_name, help: t('Gunakan 2–60 aksara. Nama pengguna anda kekal sama.')})}
      <div class="portal-profile-details"><dl class="portal-profile-facts">
        <div><dt>${t('Nama pengguna')}</dt><dd><span class="portal-profile-readonly">@${esc(profile.username)}</span><small>${t('Tidak boleh diubah.')}</small></dd></div>
        <div><dt>${t('E-mel')}</dt><dd><span class="portal-profile-readonly">${legacy ? t('Tiada e-mel berdaftar (akaun lama).') : esc(email)}</span></dd></div>
        <div><dt>${t('Status pengesahan e-mel')}</dt><dd><span class="portal-profile-identity-state">${legacy ? t('Tidak berkenaan') : profile.email_verified === true ? t('Disahkan') : profile.email_verified === false ? t('Belum disahkan') : t('Belum tersedia')}</span></dd></div>
        <div><dt>${t('Peranan')}</dt><dd><span class="portal-profile-readonly">${role}</span><small>${t('Peranan ditetapkan oleh sistem.')}</small></dd></div>
        <div><dt>${t('Kelas')}</dt><dd><span class="portal-profile-readonly">${classNames.length ? classNames.join(', ') : t('Belum ada kelas.')}</span><small>${t('Keahlian kelas diurus dalam ruang kelas.')}</small>${classes.length ? `<details class="portal-profile-class-details"><summary>${t('Lihat maklumat kelas')}</summary><ul class="portal-profile-classes">${classes.map(c => `<li><b>${esc(c.name)}</b><span>${t('Guru')}: ${c.teacher_name ? esc(c.teacher_name) : c.teacher_id === profile.id && profile.role === 'teacher' ? esc(profile.display_name) : t('Maklumat guru belum tersedia')}</span>${button(t('Buka kelas'), 'profile-class', {id: c.id, quiet: true})}</li>`).join('')}</ul></details>` : profile.role === 'student' ? `<p>${t('Gunakan PIN daripada guru untuk menyertai kelas.')}</p>${button(t('Sertai kelas'), 'profile-join', {primary: true})}` : button(t('Buka ruang kelas'), 'profile-back', {quiet: true})}</dd></div>
      </dl></div>
      ${formError()}<div class="portal-profile-actions">${submit(t('Simpan perubahan'))}${button(t('Batal'), 'profile-back', {quiet: true})}</div>
    </form></section><aside class="portal-panel portal-profile-preview-card" aria-labelledby="portal-profile-preview-title"><h2 id="portal-profile-preview-title">${t('Pratonton profil')}</h2><p class="portal-muted">${t('Paparan ringkas akaun anda.')}</p>
      <div class="portal-profile-preview" data-profile-preview><span class="portal-avatar" data-profile-preview-avatar>${avatarArt(profile.avatar)}</span><b data-profile-preview-name>${esc(profile.display_name)}</b><span class="portal-profile-role-chip">${role}</span>${classNames.length ? `<ul class="portal-profile-preview-classes">${classNames.map(name => `<li>${name}</li>`).join('')}</ul>` : `<span class="portal-profile-preview-empty">${t('Belum ada kelas.')}</span>`}<small data-profile-preview-state>${t('Pratonton nama dan avatar')}</small></div>
    </aside></div></div>`;
}
